from lib import *
M='maths'
# ---------- Animal Jumps ----------
build(M,'animal-jumps','jump-data-and-simple-tables',"Factors, multiples and arrays",
 "The mystery box",
 "A magic box multiplies every number put into it. Out come 28, 36, 48 and 72. Can you guess the multiplier? It could be 1, 2 or 4 - and more than one works! Today we find out why.",
 [("Look at the numbers that came out of the box: 28, 36, 48 and 72.","28, 36, 48, 72"),
  ("The multipliers 1, 2 and 4 work for all of them. These are the common factors of the four numbers.","factor"),
  ("The numbers 28, 36, 48 and 72 are multiples of 1, 2 and 4. The product of two or more factors gives a multiple.","multiple"),
  ("A number arranged in an array shows its factors. For 15, make 3 rows of 5 squares: 3 x 5 = 15, so 3 and 5 are factors and 15 is their multiple.","array"),
  ("Make arrays for 12: 3 x 4, 2 x 6 and 1 x 12. So the factors of 12 are 1, 2, 3, 4, 6 and 12.","12"),
  ("12 is a multiple of each of these factors. Every number is a multiple of itself, and 1 and the number itself are always factors.","1 and itself"),
  ("A number like 13 or 37 has only two factors, 1 and itself. Such numbers are called prime numbers. Try making arrays for 13 and you will see only one array, 1 x 13.","prime"),
  ("Not every number has many factors. 15 has four factors: 1, 3, 5 and 15 - so only two arrays, 1 x 15 and 3 x 5.","15")],
 ("List all the factors of 20.",[("Find pairs that multiply to 20: 1 x 20, 2 x 10, 4 x 5.","Try dividing 20 by 1, 2, 3, 4, 5 and keep those with no remainder."),("Write the numbers from the pairs in order: 1, 2, 4, 5, 10, 20.","Each number in a pair is a factor."),("20 is a multiple of every one of these factors.","If 4 x 5 = 20, then 20 is a multiple of 4 and of 5.")]),
 ("What is the difference between a factor and a multiple? Use 12 to explain.",["Factors divide a number completely","Multiples come from multiplying","12 has factors 1, 2, 3, 4, 6, 12 and is a multiple of each"],["Thinking 12 is a factor of 6"]),
 ["Factors are the numbers that divide a number completely; multiples are what we get by multiplying.","An array shows factor pairs: 3 x 4 = 12 means 3 and 4 are factors of 12.","1 and the number itself are factors of every number; a number with only these two factors is prime.","Common factors of 28, 36, 48 and 72 include 1, 2 and 4."],
 [mcq("r1-fa1",1,"Which of these is a factor of 12?","4",[("5","12 divided by 5 leaves a remainder, so 5 is not a factor."),("8","8 x 1 = 8 and 8 x 2 = 16 - 12 is not in the 8 table.")],"4 x 3 = 12, so 4 divides 12 exactly."),
  tf("r1-fa2",1,"The number itself is always a multiple of itself.",True,"Any number x 1 = itself, so it is its own multiple."),
  tf("r2-fa3",2,"13 has exactly two factors, 1 and 13.",True,"13 only makes the array 1 x 13, so it is a prime number."),
  num("r2-fa4",2,"How many factors does 12 have?",6,"The factors are 1, 2, 3, 4, 6 and 12.",[(4,"You may have counted only 1, 2, 3, 4. Also count 6 and 12.")]),
  mcq("r2-fa5",2,"Which number can be arranged in only one array (1 row of the number)?","37",[("15","15 also gives 3 x 5."),("54","54 has many factors such as 2, 3, 6, 9.")],"37 is prime. Only 1 x 37 works."),
  short("r3-fa6",3,"Write the factors of 15 in order, separated by commas.",["1,3,5,15","1, 3, 5, 15"],"3 x 5 = 15 and 1 x 15 = 15 give 1, 3, 5, 15.",[("3,5","1 and 15 are also factors.")]),
  tf("r3-fa7",3,"Factors of an odd number cannot be even.",True,"An even number divides only even numbers exactly, so an odd number cannot have an even factor."),
  tf("r3-fa8",3,"Factors of even numbers must be even.",False,"12 is even but 3 is its factor and 3 is odd.")],
 svg=("c5-arrays-12.svg","Three arrays of 12 squares: 1 row of 12, 2 rows of 6 and 3 rows of 4","Arrays of 12 show its factors"))

build(M,'animal-jumps','equal-jumps-and-multiples',"Common multiples and common factors on the number line",
 "Rabbit and frog",
 "A rabbit jumps 4 at a time and a frog jumps 3 at a time. Both start at 0. Where do they land on the same spot? In the book they first meet at 12.",
 [("The rabbit lands on 4, 8, 12, 16 and so on - these are the multiples of 4.","4, 8, 12"),
  ("The frog lands on 3, 6, 9, 12, 15 - the multiples of 3.","3, 6, 9, 12"),
  ("The numbers that both animals touch are called the common multiples of 3 and 4.","common multiple"),
  ("12 is the first common multiple of 3 and 4. The next one is 24. You can keep going on the number line or use the tables of 3 and 4.","12, 24"),
  ("Another pair: a spider jumps 3 and a grasshopper jumps 6. They meet at 6 and 12, and again at 18, 24 and so on.","3 and 6"),
  ("The multiples of 4 are 4, 8, 12, 16 and of 6 are 6, 12, 18. 12 and 24 are common multiples of 4 and 6.","4 and 6"),
  ("A common factor of two or more numbers divides each of the numbers exactly. 3 is a common factor of 9, 21, 39 and 57. 1 is a common factor of every pair of numbers.","common factor"),
  ("Common factors of 24 and 36 are 1, 2, 3, 4, 6 and 12. A jump of 12 steps from 0 reaches both 24 and 36, and so does a jump of 2, 3, 4 or 6.","24 and 36"),
  ("The common factors of 12 and 13 are only 1. Notice that the common multiples of two numbers never end, but their common factors are few.","12 and 13")],
 ("Sher Khan the tiger hunts every 3rd day and Bagheera the panther every 5th day. If both hunt today, on which days will they hunt together?",[("Multiples of 3: 3, 6, 9, 12, 15, 18 ... and multiples of 5: 5, 10, 15, 20 ...","Hunting days are the multiples."),("15 is in both lists. The next common multiple is 30.","Common multiples are the days both hunt."),("They hunt together on days 15, 30, 45 ... every 15th day.","3 x 5 = 15 because 3 and 5 have no common factor except 1.")]),
 ("Explain how to find the common multiples of 4 and 6.",["List multiples of 4","List multiples of 6","Pick the numbers that are in both lists: 12, 24"],["Choosing common factors instead of multiples"]),
 ["Common multiples are numbers that are multiples of two or more numbers.","The first common multiple of 3 and 4 is 12; the next is 24.","Common factors exactly divide all the numbers; 1 is always a common factor.","The common factors of 24 and 36 are 1, 2, 3, 4, 6, 12."],
 [mcq("r1-eq1",1,"The first common multiple of 3 and 4 is","12",[("7","7 is 3 + 4, not a multiple of either number."),("6","6 is a multiple of 3 but not of 4.")],"12 is in the table of 3 (3 x 4) and of 4 (4 x 3)."),
  num("r1-eq2",1,"Write the next common multiple of 3 and 4 after 12.",24,"Common multiples of 3 and 4 are 12, 24, 36 ... they go up by 12.",[(15,"15 is a multiple of 3 only.")]),
  mcq("r2-eq3",2,"Which of these is a common multiple of 4 and 6?","12",[("10","10 is not in the 4 table."),("16","16 is in the 4 table but not the 6 table.")],"12 = 4 x 3 = 6 x 2."),
  tf("r2-eq4",2,"The only common factor of 12 and 13 is 1.",True,"13 is prime. Its only factors are 1 and 13, and 13 does not divide 12."),
  short("r2-eq5",2,"Sher Khan hunts every 3rd day and Bagheera every 5th day. After how many days will they first hunt together? Write the number.",["15"],"The first common multiple of 3 and 5 is 15.",[("8","8 is 3 + 5, which is not how common multiples work.")]),
  mcq("r3-eq6",3,"Which of these is a common factor of 24 and 36?","6",[("5","5 does not divide 24."),("8","8 divides 24 but not 36.")],"6 x 4 = 24 and 6 x 6 = 36."),
  tf("r3-eq7",3,"Multiples of odd numbers cannot be even.",False,"3 is odd but 3 x 2 = 6 is even."),
  tf("r3-eq8",3,"0 cannot be a factor of any number.",True,"We cannot divide by 0, so 0 is never a factor."),
  num("r3-eq9",3,"How many common factors do 24 and 36 have?",6,"They are 1, 2, 3, 4, 6, 12.",[(4,"Count 6 and 12 too.")])],
 svg=("c5-common-multiples.svg","Number line showing jumps of 3 and 4 that meet at 12","Jumps of 3 and 4 meet at 12"))

# ---------- Racing Seconds ----------
build(M,'racing-seconds','seconds-minutes-and-hours',"Seconds, minutes and hours",
 "Who won the race?",
 "Akira, Sunita and Mary ran a 200 metre walking race. The winner took 1 minute 55 seconds, the second 1 minute 56 seconds and the third 1 minute 57 seconds. Minutes alone cannot tell us who won - we need a smaller unit: the second.",
 [("A race has small differences in time, so we use a new unit called the second.","second"),
  ("The book tells us: 1 minute = 60 seconds. The second hand of a clock moves 60 steps in one full round, which takes exactly 1 minute.","1 min = 60 s"),
  ("And 1 hour = 60 minutes, so 1 hour = 60 x 60 = 3600 seconds.","1 hour = 60 min"),
  ("Some things take seconds, like blinking, switching on a light or snapping fingers. Some take minutes, like filling a bucket or having a bath.","seconds or minutes?"),
  ("Estimate first and then check. In the book you estimate how many balloons you can blow, push-ups, breaths or hops on one leg in a minute, and then verify.","estimate"),
  ("To read the time taken on a clock, look at the second hand. If Rani's second hand moved from 12 to 4, she took 20 seconds, because each number on the clock is 5 seconds.","each number = 5 seconds"),
  ("When you draw the missing seconds hand: if Raghu took 20 seconds, the hand moves 4 numbers, to 4; 30 seconds is the 6; 60 seconds is a full round back to the same place.","draw the hand")],
 ("The second hand starts at 12 and stops at 8. How many seconds have passed?",[("From 12 to 8 the hand crosses 8 numbers.","Each number on the clock face is 5 seconds."),("8 x 5 = 40.","Multiply the number of numbers by 5."),("So 40 seconds passed.","Full circle would be 60 seconds.")]),
 ("How many seconds are there in 1 minute and how do you read seconds on a clock?",["1 minute = 60 seconds","Each number on the clock face stands for 5 seconds","A full round of the second hand is 1 minute"],["Reading the hour hand instead of the second hand"]),
 ["1 minute = 60 seconds and 1 hour = 60 minutes.","Seconds measure very short times like blinking or a race.","On a clock each number is 5 seconds for the second hand.","Estimate the time first, then check by doing."],
 [num("r1-sm1",1,"How many seconds are in 1 minute?",60,"1 min = 60 s.",[(100,"Time is counted in 60s, not 100s.")]),
  mcq("r1-sm2",1,"Which activity takes about a few seconds?","Snapping your fingers",[("Having a bath","A bath takes many minutes."),("Filling a bucket from the tap","That takes a minute or more.")],"Snapping fingers is a very quick action."),
  num("r2-sm3",2,"The second hand moves from 12 to 4. How many seconds is that?",20,"4 numbers x 5 seconds = 20 seconds.",[(4,"Each number is 5 seconds, so multiply by 5.")]),
  num("r2-sm4",2,"How many seconds are in 2 minutes?",120,"2 x 60 = 120 seconds.",[(60,"That is 1 minute.")]),
  tf("r2-sm5",2,"The second hand takes 1 minute to go once round the clock.",True,"60 steps of 1 second each make 1 minute."),
  mcq("r3-sm6",3,"A runner takes 1 minute 56 seconds. Another takes 1 minute 55 seconds. Who is faster?","The one who took 1 minute 55 seconds",[("The one who took 1 minute 56 seconds","A smaller time means faster.")],"Less time in a race means a faster runner."),
  num("r3-sm7",3,"How many seconds are in 1 hour?",3600,"60 minutes x 60 seconds = 3600 seconds.",[(360,"Remember 60 x 60, not 60 x 6.")])],
 svg=("c5-seconds-clock.svg","A clock face with a second hand","The second hand shows seconds"))

build(M,'racing-seconds','reading-clocks-and-24-hour-time',"12-hour and 24-hour time",
 "Train timetable",
 "A train ticket says 17:30. Is that morning or evening? The 24-hour clock tells us exactly, with no a.m. or p.m. Let us learn to convert.",
 [("In the 12-hour format we write a.m. for the time from midnight to noon and p.m. for noon to midnight.","a.m. and p.m."),
  ("The 24-hour format counts the hours from 00:00 to 24:00 and has no a.m. or p.m.","24-hour"),
  ("For a.m. times the hour digits stay the same. 05:30 a.m. is 05:30 hours and 11:55 a.m. is 11:55 hours.","a.m. same"),
  ("For p.m. times add 12 to the hour. 02:30 p.m. is 14:30 hours; 05:30 p.m. is 17:30 hours; 09:35 p.m. is 21:35 hours.","p.m. add 12"),
  ("To go back, subtract 12: 20:45 hours is 08:45 p.m., and 23:45 hours is 11:45 p.m.","subtract 12"),
  ("Match examples from the book: 06:30 a.m. = 06:30, 04:30 a.m. = 04:30, 01:30 a.m. = 01:30, 07:30 p.m. = 19:30, 08:45 p.m. = 20:45, 11:45 p.m. = 23:45.","match")],
 ("Write 09:35 p.m. in 24-hour format.",[("It is a p.m. time, so add 12 to the hour.","a.m. times stay the same; p.m. times add 12."),("9 + 12 = 21, so the time is 21:35.","The minutes do not change."),("Answer: 21:35 hours.","Check: 21:35 minus 12 hours is 9:35 p.m.")]),
 ("How do you change 5:30 p.m. into 24-hour time?",["It is p.m. so add 12","5 + 12 = 17","The minutes stay the same: 17:30"],["Adding 12 to a.m. times"]),
 ["The 24-hour clock runs from 00:00 to 24:00 with no a.m. or p.m.","For a.m. times the hour stays the same.","For p.m. times add 12 to the hour.","To go back from 24-hour time subtract 12 from the hour if it is above 12."],
 [mcq("r1-tf1",1,"2:30 p.m. in 24-hour format is","14:30",[("02:30","That is 2:30 a.m."),("12:30","Add 12 to the 2, not to the minutes.")],"2 + 12 = 14."),
  mcq("r1-tf2",1,"05:30 a.m. in 24-hour format is","05:30",[("17:30","That is 5:30 p.m."),("15:30","We do not add anything to a.m. times.")],"a.m. times stay the same."),
  num("r2-tf3",2,"Write 5:30 p.m. as an hour of the 24-hour clock (answer the hour number).",17,"5 + 12 = 17.",[(5,"p.m. means we add 12.")]),
  mcq("r2-tf4",2,"20:45 hours is the same as","08:45 p.m.",[("08:45 a.m.","a.m. times are below 12:00."),("02:45 p.m.","20 - 12 = 8, not 2.")],"20 - 12 = 8, so 08:45 p.m."),
  num("r2-tf5",2,"How many minutes pass from 1:15 p.m. to 1:42 p.m.?",27,"42 - 15 = 27 minutes.",[(57,"Subtract the minutes; do not add.")]),
  num("r3-tf6",3,"How many hours from 3:18 p.m. to 8:18 p.m.?",5,"The minutes are the same, so 8 - 3 = 5 hours.",[(11,"You added the hours.")]),
  mcq("r3-tf7",3,"Raghav painted for 1 hour 20 minutes, Rani for 2 hours 10 minutes and Ritu for 1 hour 35 minutes. Who took the longest?","Rani",[("Raghav","1 h 20 min is the least."),("Ritu","Ritu took 1 h 35 min, less than Rani.")],"2 h 10 min is the biggest time.")],
 svg=("c5-24-hour-time.svg","A day timeline from 00:00 to 24:00 showing a.m. and p.m. hours","a.m. same, p.m. add 12"))

build(M,'racing-seconds','duration-and-time-problems',"How long did it take? Time duration",
 "Raghav's yoga",
 "Raghav starts yoga at one time and finishes at another. How long did he practise? The time between two clock times is called the duration.",
 [("Duration means how much time has passed between a start and an end.","duration"),
  ("If both times have the same minutes, just subtract the hours. 3:18 p.m. to 8:18 p.m. is 5 hours.","same minutes"),
  ("If both times have the same hour, subtract the minutes. 1:15 p.m. to 1:42 p.m. is 27 minutes.","same hour"),
  ("For 9:15 a.m. to 11:30 a.m. first count whole hours to 11:15, which is 2 hours, then 15 more minutes: 2 hours 15 minutes.","hours then minutes"),
  ("To compare times, write them in the same units. 1 h 20 min is 80 minutes, 2 h 10 min is 130 minutes and 1 h 35 min is 95 minutes. Rani took the longest and Raghav the least.","compare"),
  ("A stopwatch or a second hand is used when the duration is very small, such as skipping 10 times or writing your name.","stopwatch")],
 ("Find the time from 9:15 a.m. to 11:30 a.m.",[("From 9:15 to 11:15 is 2 hours.","Make the minutes equal first."),("From 11:15 to 11:30 is 15 minutes.","Subtract 30 - 15."),("Total duration is 2 hours 15 minutes.","Add the hours and minutes.")]),
 ("How do you find the time that passed between 9:15 a.m. and 11:30 a.m.?",["Count whole hours first","Then count the extra minutes","Add: 2 h 15 min"],["Subtracting 9 from 11 and 15 from 30 separately in the wrong order"]),
 ["Duration is the time between a start and an end.","Subtract hours when minutes are the same, and minutes when hours are the same.","Convert to minutes to compare times such as 1 h 20 min and 2 h 10 min.","Use seconds for very short activities."],
 [num("r1-dt1",1,"How many hours from 3:18 p.m. to 8:18 p.m.?",5,"8 - 3 = 5 hours.",[(11,"You added instead of subtracting.")]),
  num("r1-dt2",1,"How many minutes from 1:15 p.m. to 1:42 p.m.?",27,"42 - 15 = 27.",[(57,"Subtract, do not add.")]),
  mcq("r2-dt3",2,"From 9:15 a.m. to 11:30 a.m. is","2 hours 15 minutes",[("2 hours 45 minutes","30 - 15 is 15 minutes, not 45."),("1 hour 15 minutes","11 - 9 = 2 hours, not 1.")],"2 hours to 11:15 and 15 more minutes."),
  num("r2-dt4",2,"1 hour 20 minutes is how many minutes?",80,"60 + 20 = 80.",[(120,"1 hour is 60 minutes, not 100.")]),
  mcq("r3-dt5",3,"Raghav took 1 h 20 min, Rani 2 h 10 min and Ritu 1 h 35 min to paint. Who took the least time?","Raghav",[("Rani","Rani took the most time."),("Ritu","1 h 35 min is more than 1 h 20 min.")],"80 minutes is the smallest of 80, 130 and 95."),
  num("r3-dt6",3,"A film starts at 4:15 p.m. and ends at 6:45 p.m. How many minutes does it last in total?",150,"2 h 30 min = 120 + 30 = 150 minutes.",[(30,"Remember to include the 2 hours.")])])

# ---------- Maps ----------
build(M,'maps-and-locations','directions-and-routes-on-maps',"Directions and routes on maps",
 "How do birds find their way?",
 "Siberian cranes fly all the way from cold Siberia to the Bharatpur Bird Sanctuary in Rajasthan. How do they know the direction? We humans keep track of directions too, and one way is by facing the rising Sun.",
 [("There are four main directions called cardinal directions: North, East, South and West.","N E S W"),
  ("The Sun rises in the East. If you stand facing the rising Sun, you are facing East.","East"),
  ("When you face East, your left hand points to North, your right hand points to South and the West is behind you. Manu in the book does exactly this.","left = North"),
  ("A compass is a tool that always shows the direction of North. Using a compass is another way to find directions.","compass"),
  ("A map uses a small compass sign, often in a corner, to show where North is. We read other directions from it.","map direction sign"),
  ("To describe a route, say where to start, which direction to go, where to turn left or right and which road to take. The bus in the Zoo Trip starts from the parking area, goes north, then turns right on a road to reach Stop 1.","route"),
  ("In the room map we write the directions of objects like the window, bed, cupboard and bedside table in relation to the girl standing in the centre.","room map"),
  ("In the metro map different coloured lines show different routes. Find the Qutb Minar station on the Yellow Line and the Supreme Court station on the Blue Line, and use the key to trace routes and change lines at interchange stations.","metro map")],
 ("Manu faces the rising Sun. Which direction is his left hand pointing to?",[("The Sun rises in the East, so Manu faces East.","Rising Sun = East."),("Standing facing East, North is on the left.","N, E, S, W go clockwise; North is to the left of East."),("So his left hand points North and his right hand points South.","West is behind him.")]),
 ("How can you find directions without a compass?",["The Sun rises in the East","Facing East, left is North and right is South","West is behind you"],["Thinking the Sun rises in the West"]),
 ["The four cardinal directions are North, East, South and West.","Facing the rising Sun you face East: left is North, right is South, behind is West.","A compass or the sign on a map shows North.","To give a route, tell the direction, the turns and the roads."],
 [mcq("r1-dr1",1,"The Sun rises in the","East",[("West","The Sun sets in the West."),("North","North is on your left when you face East.")],"It rises in the East."),
  mcq("r1-dr2",1,"You face the rising Sun. Your left hand points","North",[("South","South is on your right."),("West","West is behind you.")],"Facing East, left is North."),
  mcq("r2-dr3",2,"You face the rising Sun. What is behind you?","West",[("East","East is in front of you."),("North","North is on your left.")],"Opposite of East is West."),
  short("r2-dr4",2,"Write the direction opposite to North.",["south"],"North and South are opposite; so are East and West.",[("east","East is opposite to West.")]),
  mcq("r2-dr5",2,"A compass needle always points to","North",[("The Sun","The needle does not follow the Sun."),("East","The needle shows North, and the other directions are read from it.")],"A compass shows North."),
  tf("r3-dr6",3,"On a metro map, different coloured lines show different routes.",True,"Each colour is a different metro line; the key tells which."),
  mcq("r3-dr7",3,"If you face North, your right hand points","East",[("West","West is on your left."),("South","South is behind you.")],"Turning clockwise from North gives East."),
  tf("r3-dr8",3,"To describe a route we need the direction of travel and where to turn.",True,"Direction, turns and road names make a route clear.")],
 svg=("c5-compass-rose.svg","A compass rose showing North at the top, East on the right, South at the bottom and West on the left","The four cardinal directions"))

build(M,'maps-and-locations','reading-simple-maps',"Reading simple maps and keys",
 "A map of my school",
 "Draw the school ground from above, with symbols for gate, road, building, tank, path, garden and tree. A friend can then find the hidden objects you marked with red dots! That is what a map does.",
 [("A map is a drawing of a place as seen from above.","map"),
  ("A map uses symbols to show things like a gate, road, building, tank, wall, fence, seat or bench, path, garden and tree.","symbols"),
  ("The key (or legend) explains what each symbol means. Always read the key first.","key"),
  ("A direction sign (N, E, S, W) shows where North is on the map.","direction sign"),
  ("Maps help in everyday life: the street map in the Zoo Trip helps the bus reach each stop and the metro map shows lines and stations.","uses"),
  ("To locate a place, find a clear landmark. In the street map, Jaideep's house, the hospital and the park show whose house is east of whose.","landmarks"),
  ("To make your own map: draw the outline, choose symbols, put a key, add the N sign and mark the hidden objects with red dots or flags.","make a map")],
 ("In the street map, how would you find the nearest bus stop from a house?",[("Find the house and look for the stop symbol nearest to it.","Use landmarks and the key."),("Trace the road between them with your finger.","Use the roads drawn."),("Use the direction sign to say whether to go North, South, East or West.","This gives clear directions.")]),
 ("Why do we put a key and a direction sign on a map?",["The key explains the symbols","The direction sign shows North","Together they let others read the map"],["Skipping the key"]),
 ["A map shows a place as seen from above.","Symbols stand for real things; the key explains them.","The direction sign shows North.","Maps help us find places and plan routes."],
 [mcq("r1-rm1",1,"The key of a map tells us","what each symbol means",[("the size of the school","The key explains the symbols, not the size."),("who made the map","The key is about the symbols.")],"The key explains symbols."),
  tf("r1-rm2",1,"A map shows a place as seen from above.",True,"Maps are drawn from a top view."),
  mcq("r2-rm3",2,"A sign with N, E, S and W on a map shows","directions",[("distance","It does not give distance."),("colours","Colours have a separate key.")],"It tells us where North is."),
  short("r2-rm4",2,"What do we call the box that explains the symbols on a map? One word.",["key","legend"],"The key (legend) lists each symbol and its meaning.",[("title","The title names the map, not the symbols.")]),
  mcq("r3-rm5",3,"Which is the best landmark to help a friend find your house on a map?","A tank or hospital near it",[("A tiny stone","It is too small to find."),("A cloud","Clouds move.")],"Good landmarks are big and fixed."),
  tf("r3-rm6",3,"A map without a direction sign cannot be read at all.",False,"We can still read it, but the sign makes giving directions easy.")],
 svg=("c5-grid-locations.svg","A grid map with squares labelled by letters and numbers","Locating places on a grid"))

# ---------- Data ----------
build(M,'data-through-pictures','collecting-and-showing-data',"Collecting and recording data",
 "Child TV reporters",
 "Samaira and Kabir act like TV reporters and ask 35 friends: How many hours do you watch TV in a day? The answers are all over the notebook - half an hour, 1 hour, 2 hours... How do we make sense of it?",
 [("Data is information collected to answer a question, like the hours of TV watched by 35 friends.","data"),
  ("Raw data is hard to read. We organise it in a table with groups: half an hour, 1 hour, one and a half hours, 2 hours and more than 2 hours.","table"),
  ("Use tally marks to count: make four straight lines and cross them for the fifth, so each bunch is 5.","tally marks"),
  ("The numbers in the table tell us how many children are in each group. The total must be 35.","total = 35"),
  ("Then we read the table: how many children watch for more than half an hour, how many for less than two hours and so on.","read the table"),
  ("Some data is better shown by pictures: Joseph Uncle has too many toys, board games and sports items to draw one picture for each, so he draws a pictograph.","too many items"),
  ("Showing data helps us tell a story, such as how many hours of TV is too much, and make choices, such as how long to watch.","why show data")],
 ("In a class survey, 3 children watch TV for half an hour, 8 for 1 hour, 12 for one and a half hours, 7 for 2 hours and 5 for more than 2 hours. How many children were asked?",[("Add all the groups: 3 + 8 + 12 + 7 + 5.","The total number of children is the sum of all groups."),("3 + 8 = 11, 11 + 12 = 23, 23 + 7 = 30, 30 + 5 = 35.","Add step by step."),("35 children were asked.","This matches the 35 friends in the book.")]),
 ("How do you collect and record data using tally marks?",["Ask the question to everyone","Make a mark for each answer","Group marks in fives and count"],["Counting without grouping"]),
 ["Data is information we collect.","A table with groups makes the data easy to read.","Tally marks in bunches of 5 help counting.","A total check: all groups together should equal the number of people asked."],
 [mcq("r1-cs1",1,"Tally marks are grouped in","fives",[("tens","Bunches of 10 are too big."),("twos","Fives are the standard group.")],"Four lines crossed by one make five."),
  tf("r1-cs2",1,"A table helps us read data easily.",True,"Groups and counts make the pattern clear."),
  num("r2-cs3",2,"3 children watch half an hour, 8 watch 1 hour, 12 watch 1.5 hours, 7 watch 2 hours and 5 watch more. How many children in all?",35,"3 + 8 + 12 + 7 + 5 = 35.",[(30,"You may have left out the last group.")]),
  mcq("r2-cs4",2,"Which is raw data?","A list of 35 answers in a notebook",[("A bar graph","A graph is organised data."),("A pictograph","A pictograph is organised data.")],"Raw data is the unorganised list."),
  tf("r3-cs5",3,"The numbers in all groups of a table should add up to the number of people asked.",True,"Every person falls in exactly one group."),
  mcq("r3-cs6",3,"Joseph Uncle has hundreds of toys. What helps him show them easily?","A pictograph with a scale",[("Drawing every toy","Too many to draw."),("Writing nothing","We still need to show data.")],"A scale lets one icon stand for many items.")])

build(M,'data-through-pictures','pictographs',"Pictographs and scales",
 "Stock-taking in a shop",
 "Joseph Uncle's shop has toys, board games and sports items. Drawing one picture per item would take forever. So he draws one picture for every 5 items. That is a scale.",
 [("A pictograph uses pictures or icons to show data.","pictograph"),
  ("A scale tells us how many items one icon stands for. In Joseph Uncle's pictograph, 1 icon = 5 items.","1 icon = 5"),
  ("To find a total, count the icons and multiply by the scale. 4 icons x 5 = 20 items.","icons x scale"),
  ("Deepti counted two-wheelers passing her house and used 1 icon = 3 two-wheelers. 7 icons mean 7 x 3 = 21 two-wheelers.","1 icon = 3"),
  ("A different scale changes the number of icons but not the data. We can choose a scale that is easy for the data, like 2, 5 or 10.","choose a scale"),
  ("We compare rows: the day with the most icons had the most two-wheelers, and the difference between two rows is the difference in icons times the scale.","compare rows"),
  ("Reading a pictograph: first read the key, then count the icons, then multiply.","read the key")],
 ("In a pictograph 1 icon = 3 two-wheelers. Monday has 8 icons and Wednesday has 5 icons. How many fewer two-wheelers were seen on Wednesday than on Monday?",[("Difference in icons: 8 - 5 = 3.","Compare the rows."),("Multiply by the scale: 3 x 3 = 9.","Each icon is 3 two-wheelers."),("9 fewer two-wheelers.","Check: 24 on Monday and 15 on Wednesday, the difference is 9.")]),
 ("How do you read a pictograph with a scale?",["Read the key to see what one icon means","Count the icons","Multiply the number of icons by the scale"],["Counting icons as one each"]),
 ["A pictograph shows data using icons.","The scale tells how many items one icon stands for.","Total = number of icons x scale.","Choose a scale that suits the data."],
 [mcq("r1-pg1",1,"If 1 icon = 5 toys, 4 icons show","20 toys",[("4 toys","You forgot the scale."),("9 toys","You added instead of multiplying.")],"4 x 5 = 20."),
  num("r1-pg2",1,"1 icon = 3 two-wheelers. How many two-wheelers do 7 icons show?",21,"7 x 3 = 21.",[(7,"Multiply by the scale.")]),
  mcq("r2-pg3",2,"Why do we use a scale?","So one icon can stand for many items",[("To make graphs colourful","Colour is not the reason."),("To hide the numbers","A scale makes data easier to read.")],"A scale reduces the number of icons."),
  num("r2-pg4",2,"1 icon = 5 items. 6 icons show how many items?",30,"6 x 5 = 30.",[(11,"Do not add.")]),
  num("r2-pg5",2,"With 1 icon = 3, Monday has 8 icons and Wednesday 5 icons. How many fewer on Wednesday?",9,"3 icons x 3 = 9.",[(3,"Multiply 3 icons by the scale 3.")]),
  tf("r3-pg6",3,"Changing the scale changes the data.",False,"The data stays the same; only the number of icons changes."),
  mcq("r3-pg7",3,"Joseph Uncle has 45 board games. With 1 icon = 5, how many icons does he draw?","9",[("5","45 is not 5 icons."),("45","That is without a scale.")],"45 / 5 = 9.")],
 svg=("c5-pictograph-scale.svg","A pictograph with rows of circles for cars, balls and dolls where one circle stands for 5 toys","One icon stands for 5 toys"))

build(M,'data-through-pictures','reading-bar-graphs',"Reading and making bar graphs",
 "Raman's and Sheela's day",
 "One day Raman and Sheela wrote how they spent their day. Raman used circles, one for each hour. Sheela drew tall bars. Both show the same kind of facts, but Sheela's way is called a bar graph.",
 [("Raman recorded his routine in a table with one circle for each hour: sleeping, school, studying, eating and playing and other activities.","table of hours"),
  ("Sheela drew vertical bars. The vertical line shows the number of hours and the horizontal base shows the different activities.","axes"),
  ("The taller the bar, the more hours were spent on that activity.","bar height"),
  ("To read a bar graph, find the top of a bar and look across to the number on the vertical line.","read the bar"),
  ("Compare bars to answer questions: who sleeps more, who spends more hours in school and how many more hours Sheela studies than Raman.","compare bars"),
  ("To make your own bar graph: write the activities on the base, mark the hours on the vertical line, and draw a bar of equal width up to the right height for each activity. You can use paper strips pasted along the base to compare finger lengths.","draw bars"),
  ("A pictograph shows data with icons; a bar graph shows data with bars. Both help us see and compare quickly.","two ways")],
 ("A bar for studying reaches 4 and a bar for eating and playing reaches 3. Which is more and by how much?",[("Read the top of each bar on the vertical line: 4 and 3.","Look across from the top of the bar."),("4 is more than 3.","Taller bar means more hours."),("The difference is 4 - 3 = 1 hour.","Subtract to compare.")]),
 ("How do you read the height of a bar in a bar graph?",["Look at the top of the bar","Read across to the vertical line","The number is the value"],["Reading the base instead of the vertical line"]),
 ["A bar graph uses bars of equal width; taller bars mean more.","The vertical line shows the number and the base shows the groups.","Compare bars by subtracting their heights.","We can make a bar graph of our own day."],
 [mcq("r1-bg1",1,"In a bar graph, a taller bar means","a bigger number",[("a smaller number","The longer the bar, the bigger the value."),("nothing","Height shows the value.")],"Taller means more hours."),
  mcq("r1-bg2",1,"The vertical line of Sheela's graph shows","the number of hours",[("the names of activities","The activities are on the base."),("the date","Date is not shown.")],"The vertical line shows hours."),
  mcq("r2-bg3",2,"The base (horizontal line) of Sheela's graph shows","different activities",[("number of hours","That is on the vertical line."),("the days of the week","Not in this graph.")],"The base lists the activities."),
  num("r2-bg4",2,"A bar reaches 4 and another reaches 3. How many more is the first?",1,"4 - 3 = 1.",[(7,"Subtract; do not add.")]),
  tf("r3-bg5",3,"All bars in a bar graph should have the same width.",True,"Equal width keeps the comparison fair."),
  mcq("r3-bg6",3,"Which shows data with icons?","Pictograph",[("Bar graph","Bar graphs use bars."),("Table","A table uses numbers.")],"A pictograph uses icons.")],
 svg=("c5-bar-graph-raman.svg","A bar graph with bars for sleeping, time in school, studying, eating and playing, and other activities","Sheela's bar graph"))
